# tools/rollup_report.py
import csv
from collections import defaultdict

def rollup(rows, key):
    acc = defaultdict(float)
    for row in rows:
        acc[row[key]] += float(row['amount'])
    return dict(sorted(acc.items(), key=lambda kv: -kv[1]))

def main(path):
    with open(path) as f:
        rows = list(csv.DictReader(f))
    by_team = rollup(rows, 'team')
    for team, total in by_team.items():
        print(f'{team}\t{total:.2f}')

if __name__ == '__main__':
    import sys; main(sys.argv[1])

// services/billing/src/meter.ts
export type SpendRecord = { tenant: string; model: string; tokensIn: number; tokensOut: number; costUsd: number };

export function emitSpend(record: SpendRecord, tags: Record<string, string>): void {
  validate(record);
  sink.write({ ...record, ...tags, at: clock.now() });
}

function validate(r: SpendRecord): void {
  if (!r.tenant) throw new RangeError('tenant required');
  if (r.costUsd < 0) throw new RangeError('cost must be non-negative');
}
